# 🛠️ Here’s your **Wolfram Language Code**:

```wolfram
(* Parameters *)
numNodes = 18;
baseRadius = 4;
amplitude = 0.5;
frequency = 5;
boundaryRadius = 5.0;
numProbes = 30;

(* Generate breathing node positions *)
breathingNodes[frame_] := Module[{angles, r, x, y},
  angles = Range[0, 2 Pi, 2 Pi/numNodes][[;; -2]];
  r = baseRadius + amplitude Sin[frequency angles + 0.2 frame];
  Transpose[{r Cos[angles], r Sin[angles]}]
];

(* Initialize Plinko Probes *)
SeedRandom[42];
probes = RandomReal[{-4.5, 4.5}, {numProbes, 2}];
probesVel = ConstantArray[{0., 0.}, numProbes];

(* Drift strength *)
driftStrength = 0.02;

(* Update Probes with breathing and reflection *)
updateProbes[frame_] := Module[{nodes, updatedProbes},
  nodes = breathingNodes[frame];

  probesVel = Table[
    Module[{nearest, dx, dy, dist, dot, norm},
      nearest = Nearest[nodes -> Automatic, probes[[i]]][[1]];
      dx = nearest[[1]] - probes[[i, 1]];
      dy = nearest[[2]] - probes[[i, 2]];

      (* Apply drift toward nearest node *)
      {probesVel[[i, 1]] + driftStrength dx, probesVel[[i, 2]] + driftStrength dy}
    ],
    {i, numProbes}
  ];

  (* Update positions *)
  probes = probes + probesVel;

  (* Reflect off boundary *)
  probes = Table[
    Module[{dist = Norm[probes[[i]]]},
      If[dist > boundaryRadius,
        (* Reflection logic *)
        Module[{norm = probes[[i]]/dist, dot},
          dot = probesVel[[i]].norm;
          probesVel[[i]] = probesVel[[i]] - 2 dot norm;
          norm * (boundaryRadius - 0.1)  (* Keep just inside boundary *)
        ],
        probes[[i]]
      ]
    ],
    {i, numProbes}
  ];
];

(* Draw the Field *)
drawField[frame_] := Module[{nodes},
  nodes = breathingNodes[frame];
  Graphics[
    {
      (* Breathing Boundary *)
      LightBlue, Dashed, Circle[{0, 0}, boundaryRadius],

      (* Breathing Nodes *)
      Black, Table[Style[Disk[nodes[[i]], 0.05], Black], {i, Length[nodes]}],

      (* Frozen Turbulence Anchors Highlight *)
      Cyan, Disk[nodes[[3]], 0.08], Disk[nodes[[8]], 0.08], Disk[nodes[[14]], 0.08],

      (* Breathing Echo Connections *)
      Table[
        {LightGray, Opacity[0.3],
         Line[{nodes[[i]], nodes[[j]]}]},
        {i, Length[nodes]}, {j, i + 1, Length[nodes]},
        If[1.5 < Norm[nodes[[i]] - nodes[[j]]] < 4.5, True, False]
      ],

      (* Plinko Probes *)
      Magenta, Opacity[0.8], Table[Disk[probes[[i]], 0.04], {i, numProbes}]
    },
    PlotRange -> {{-7, 7}, {-7, 7}},
    ImageSize -> Large,
    Axes -> False
  ]
];

(* Animate the Field *)
Manipulate[
  updateProbes[frame];
  drawField[frame],
  {frame, 0, 100, 1},
  ControlType -> Animator
]
```

